<?php
/** Shared read-only chart for corporations, organizations and civic offices. */
$hh=static fn($v)=>htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');
$renderMember=static function(array $member,string $office='')use($hh):void { ?>
 <article class="hierarchy-member lineage-node"><a class="hierarchy-portrait-link" href="/profili/?Id=<?=$member['id']?>" data-character-markers="off" aria-label="Profilo di <?=$hh($member['nome'])?>"><img class="hierarchy-portrait" src="<?=$hh($member['portrait'])?>" data-mail-fallback="<?=$hh($member['portrait_default'])?>" alt="" width="82" height="82" loading="lazy"></a><a class="hierarchy-member-name" href="/profili/?Id=<?=$member['id']?>"><strong><?=$hh($member['nome'])?></strong></a><?php if($office!==''): ?><small class="hierarchy-member-office"><?=$hh($office)?></small><?php endif; ?></article>
<?php };
$renderRole=static function(array $role)use($hh,$renderMember):void { ?>
 <article class="hierarchy-role" data-hierarchy-role="<?=(int)$role['id']?>"><header><img class="hierarchy-role-icon<?=!empty($role['badge_small'])?' is-legacy':''?>" src="<?=$hh($role['badge'])?>" alt="" width="80" height="80" loading="lazy"><h3><?=$hh($role['nome'])?></h3><div class="hierarchy-role-meta"><span>Livello <?=(int)$role['livello']?></span><?php if(!empty($role['prima'])): ?><span>Carica di ingresso</span><?php endif; ?><?php if(isset($role['stipendio'])): ?><span><?=number_format((int)$role['stipendio'],0,',','.')?> <?=alphano_currency_html()?></span><?php endif; ?></div></header>
 <?php if($role['description_html']): ?><details class="hierarchy-role-description"><summary>Descrizione della carica</summary><div><?=$role['description_html']?></div></details><?php endif; ?>
 <div class="hierarchy-role-people" aria-label="Personaggi con carica <?=$hh($role['nome'])?>"><?php if($role['members']): ?><span class="hierarchy-roster-label"><?=count($role['members'])?> <?=count($role['members'])===1?'personaggio':'personaggi'?></span><?php foreach(array_slice($role['members'],0,3) as $member)$renderMember($member,(string)$role['nome']); ?><?php if(count($role['members'])>3): ?><details class="hierarchy-extra-members"><summary>Mostra altri <?=count($role['members'])-3?> partecipanti</summary><div class="hierarchy-role-people"><?php foreach(array_slice($role['members'],3) as $member)$renderMember($member,(string)$role['nome']); ?></div></details><?php endif; ?><?php else: ?><p class="hierarchy-vacant">Carica non assegnata</p><?php endif; ?></div></article>
<?php };
$renderTiers=static function(array $tiers)use($renderRole):void{ ?><div class="hierarchy-tiers"><?php foreach($tiers as $tier): ?><div class="hierarchy-tier" data-role-level="<?=(int)$tier['level']?>"><?php foreach($tier['roles'] as $role)$renderRole($role); ?></div><?php endforeach; ?></div><?php }; ?>
<section class="hierarchy-chart" aria-label="Gerarchia delle cariche e dei personaggi">
 <header class="hierarchy-chart-intro"><div><span class="ui-eyebrow">Cariche e personaggi</span><h2>La gerarchia</h2><p>Rami dello stesso ordine e cariche dello stesso livello sono affiancati. I partecipanti compaiono sotto la propria carica.</p></div><div class="hierarchy-counts"><span><strong><?=$chart['role_count']?></strong> <?=$chart['role_count']===1?'carica':'cariche'?></span><span><strong><?=$chart['branch_count']?></strong> <?=$chart['branch_count']===1?'ramo':'rami'?></span><span><strong><?=$chart['member_count']?></strong> <?=$chart['member_count']===1?'personaggio':'personaggi'?></span></div></header>
 <?php if(!$chart['role_count']): ?><p class="ui-empty">Nessuna carica configurata.</p><?php else: ?>
 <?php if($chart['general']): ?><section class="hierarchy-general" aria-label="Cariche generali"><?php $renderTiers($chart['general']); ?></section><?php endif; ?>
 <?php foreach($chart['bands'] as $band): $bandLabel=(int)$band['level']===2147483647?'Rami da verificare':'Ordine dei rami '.(int)$band['level']; ?><section class="hierarchy-band" data-branch-columns="<?=min(3,count($band['branches']))?>" aria-label="<?=$hh($bandLabel)?>"><div class="hierarchy-band-label"><span><?=$hh($bandLabel)?></span></div><div class="hierarchy-branches"><?php foreach($band['branches'] as $branch): ?><section class="hierarchy-branch" data-hierarchy-branch="<?=(int)$branch['id']?>"><header class="hierarchy-branch-heading"><span data-icon="users" aria-hidden="true"></span><h2><?=$hh($branch['name'])?></h2></header><?php $renderTiers($branch['tiers']); ?></section><?php endforeach; ?></div></section><?php endforeach; ?>
 <?php endif; ?>
 <?php if($chart['unassigned']): ?><section class="hierarchy-unassigned"><h2>Membri senza carica assegnata</h2><div class="hierarchy-role-people"><?php foreach($chart['unassigned'] as $member)$renderMember($member); ?></div></section><?php endif; ?>
</section>
